# CDNSKEY export diagnostic (protocol != 3 in wire)
def zone_with(rdata, rrtype):
    return {"origin": "example.", "records": [
        {"name": "example.", "type": 6, "class": 1, "ttl": 100,
         "rdata": (b"\x02ns\x07example\x00\x01a\x07example\x00"
                   + (1).to_bytes(4,"big")*5)},
        {"name": "example.", "type": rrtype, "class": 1, "ttl": 100,
         "rdata": rdata},
    ]}

for rrtype, nm in ((48, "dnskey"), (60, "cdnskey")):
    try:
        dns.export_master(zone_with((257).to_bytes(2,"big")+bytes((4,8))+b"k", rrtype))
    except dns.RecordError as e:
        assert nm in str(e), (nm, e)
    else:
        raise AssertionError(str(rrtype) + " expected RecordError")

